begin;
set local lock_timeout='2s';set local statement_timeout='10s';set local search_path='';
select pg_catalog.pg_advisory_xact_lock(1261585232,1347374169);
do $legacy_writers$ declare t record;b record;a record;v_before boolean:=true;v_after boolean:=true;v_hash text;
begin
 if current_user<>'postgres' then raise exception 'K2_LEGACY_WRITER_OWNER_REQUIRED';end if;
 for t in select * from jsonb_to_recordset('[{"identity":"k2_private.guard_order_delivery_charge_v1()","body":"8a3d22eb5ee128b8b491bc9e85ff33af98704eebfafdb40a70a1d797277430af","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"k2_private.guard_order_delivery_construction_v1()","body":"35306710d9fd343d093a48031e9ce045e960adf1643372ae87162de07408af56","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true}]'::jsonb)
  as x(identity text,body text,acl text[],config text[],definer boolean) loop
  select * into b from pg_proc where oid=to_regprocedure(t.identity);
  if not found or pg_get_userbyid(b.proowner)<>'postgres' or b.proacl::text[] is distinct from t.acl
   or b.proconfig is distinct from t.config or b.prosecdef is distinct from t.definer
   or encode(extensions.digest(convert_to(replace(b.prosrc,chr(13)||chr(10),chr(10)),'UTF8'),'sha256'),'hex') is distinct from t.body
   then raise exception 'K2_LEGACY_WRITER_DEPENDENCY_DRIFT';end if;
 end loop;
 for t in select * from jsonb_to_recordset('[{"identity":"public.confirm_order_request(uuid, text)","before":"00eeb9159ab64fec2ac935d5ce6bd9a5cc07c6a4b86d3a50d02ae69f8d86b0ed","after":"1bb69c883e85cd97c5b4a4cf900bfa5a35d5afdc19f396bcc048d3fa4ed35475","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_coupon public.coupons;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''confirmed'' then return v_order; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  if v_order.status <> ''submitted'' then raise exception ''Only submitted requests can be confirmed''; end if;\n\n  perform 1 from public.coupons where id=v_order.coupon_id for update;\n  insert into public.inventory_balances(sku,location_code,on_hand,reserved)\n  select p.sku,''MANILA_MAIN'',coalesce(sum(b.quantity),0)::integer,coalesce(sum(b.reserved_quantity),0)::integer\n  from public.products p left join public.product_batches b on b.sku=p.sku\n  where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n  group by p.sku order by p.sku on conflict(sku,location_code) do nothing;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if v_order.coupon_id is not null then\n    select * into v_coupon from public.coupons where id = v_order.coupon_id for update;\n    if not found or not v_coupon.is_active or v_coupon.archived_at is not null\n       or v_coupon.starts_at > v_k2_instant or (v_coupon.ends_at is not null and v_coupon.ends_at <= v_k2_instant)\n       or (v_coupon.max_redemptions is not null and v_coupon.redemption_count >= v_coupon.max_redemptions) then\n      raise exception ''The coupon is no longer available'';\n    end if;\n    update public.coupons set redemption_count = redemption_count + 1 where id = v_coupon.id;\n    insert into public.coupon_redemptions (coupon_id, order_request_id, discount_amount)\n    values (v_coupon.id, v_order.id, v_order.discount_amount);\n  end if;\n\n  perform public.reserve_order_request_lots_v1(v_order.id, p_reason);\n\n  for v_line in select * from public.order_request_items where order_request_id = v_order.id order by created_at\n  loop\n    insert into public.orders (\n      sku, quantity, channel_source, fulfillment_method, order_status,\n      payment_status, customer_name, customer_email, total_amount, order_request_id\n    ) values (\n      v_line.sku, v_line.quantity,\n      case v_order.channel_source\n        when ''shopee'' then ''shopee''::channel_type\n        when ''lazada'' then ''lazada''::channel_type\n        when ''tiktok'' then ''tiktok''::channel_type\n        else ''website_retail''::channel_type end,\n      v_order.fulfillment_method, ''Pending''::order_status_enum, ''Unpaid''::payment_status_enum,\n      v_order.customer_name, v_order.customer_email, v_line.line_total, v_order.id\n    );\n  end loop;\n\n  update public.order_requests\n  set status = ''confirmed'', confirmed_by = auth.uid(), confirmed_at = v_k2_instant,\n      delivery_status = case when shipping_quote_status in (''platform_charged'', ''customer_confirmed'', ''waived'') then ''ready_to_pack'' else delivery_status end,\n      updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n\n  -- Owned stock leaves the sellable pool here, once. The early return above\n  -- keeps a replayed confirmation from deducting again, and the helper\n  -- itself skips already-committed allocations, so both guards agree.\n  perform public.commit_order_request_stock_v1(v_order.id, ''confirmation'', p_reason);\n\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''submitted'', ''confirmed'', p_reason, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n","acl":null,"config":["search_path=public"],"definer":true},{"identity":"public.fulfill_order_request(uuid, text)","before":"7904bf79c0965c514981d7b415eae620d26a31e1098ac7a615f4b26604c2eb2a","after":"52213a6f3f278b694f3f6bb22e21d81da080b6af8fa56052392fdd2eef8caea8","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_res public.inventory_reservations;\n  v_summary record;\n  v_balance public.inventory_balances; v_handover_reservation_ids uuid[];\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_handover_note, '''')), '''') is null then raise exception ''Courier or handover note is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''fulfilled'' then return v_order; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  if v_order.status <> ''confirmed'' then raise exception ''Order request is not confirmed''; end if;\n  if v_order.payment_status is distinct from ''verified'' then raise exception ''Payment must be explicitly verified before fulfillment''; end if;\n  if coalesce(v_order.shipping_quote_status,'''') not in (''platform_charged'', ''customer_confirmed'', ''waived'') then\n    raise exception ''Delivery charge or customer confirmation is still pending'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- Lock all affected rows before validating, in the prepared release order.\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n   and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n   order by b.sku for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id\n   order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.id in(\n   select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active'')\n   order by b.sku,b.id for update;\n  select array_agg(id) into v_handover_reservation_ids from public.inventory_reservations\n   where order_request_id=v_order.id and status=''active'';\n  if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   or exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and (i.quantity is null or i.quantity<=0 or i.quantity<>coalesce((select sum(r.quantity)\n      from public.inventory_reservations r where r.order_request_id=v_order.id\n      and r.order_request_item_id=i.id and r.sku=i.sku and r.status=''active''\n      and r.packed_quantity=r.quantity),0)))\n   or exists(select 1 from public.inventory_reservations r\n    left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n    left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n    left join public.inventory_balances bal on bal.sku=r.sku and bal.location_code=''MANILA_MAIN''\n    where r.id=any(v_handover_reservation_ids) and (i.id is null or b.id is null or bal.sku is null\n     or r.quantity<=0 or r.packed_quantity is distinct from r.quantity\n     or b.inventory_status is distinct from ''available''\n     or b.quantity<b.reserved_quantity or b.reserved_quantity<(select sum(x.quantity) from public.inventory_reservations x where x.batch_id=b.id and x.status=''active'')\n     or bal.on_hand<bal.reserved or bal.reserved<(select sum(x.quantity) from public.inventory_reservations x where x.order_request_id=v_order.id and x.sku=r.sku and x.status=''active'')\n     or not k2_private.lot_is_eligible_v1(b))) then\n   raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  -- K2_HANDOVER_STOCK_COMMITMENT_V1\n  -- Locked exact allocations must already carry attributable ownership evidence.\n  -- Never backfill a historical sale or deduct ownership for the first time at dispatch.\n  if exists(select 1 from public.inventory_reservations r where r.id=any(v_handover_reservation_ids)\n    and (r.committed_at is null or r.committed_by is null\n      or not coalesce(r.commit_cause in (''confirmation'',''payment_verification''),false))) then\n    raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  if exists (select 1 from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' and packed_quantity <> quantity) then\n    raise exception ''Every required unit must be scanned before fulfillment'';\n  end if;\n  if exists (\n    select 1 from public.inventory_reservations r join public.product_batches b on b.id = r.batch_id\n    where r.order_request_id = v_order.id and r.status = ''active''\n      and not k2_private.lot_is_eligible_v1(b)\n  ) then raise exception ''A reserved lot is no longer sellable; resolve the inventory exception first''; end if;\n\n  for v_res in select * from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' for update\n  loop\n    update public.product_batches\n    set quantity = quantity - v_res.quantity,\n        reserved_quantity = reserved_quantity - v_res.quantity,\n        inventory_status = case when quantity - v_res.quantity = 0 then ''depleted'' else inventory_status end,\n        updated_at = v_k2_instant\n    where id = v_res.batch_id and quantity >= v_res.quantity and reserved_quantity >= v_res.quantity;\n    if not found then raise exception ''Exact lot quantity mismatch for %'', v_res.sku; end if;\n    update public.inventory_reservations set status = ''fulfilled'', updated_at = v_k2_instant where id = v_res.id;\n  end loop;\n\n  for v_summary in select sku, sum(quantity)::integer quantity\n    from public.inventory_reservations where id = any(v_handover_reservation_ids) group by sku\n  loop\n    update public.inventory_balances\n    set on_hand = on_hand - v_summary.quantity, reserved = reserved - v_summary.quantity, updated_at = v_k2_instant\n    where sku = v_summary.sku and location_code = ''MANILA_MAIN''\n      and on_hand >= v_summary.quantity and reserved >= v_summary.quantity;\n    if not found then raise exception ''Inventory balance mismatch for %'', v_summary.sku; end if;\n    select * into v_balance from public.inventory_balances where sku = v_summary.sku and location_code = ''MANILA_MAIN'';\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set stock_available = (\n      select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n      where b.sku = v_summary.sku and b.inventory_status = ''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku = v_summary.sku;\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_summary.sku, ''MANILA_MAIN'', ''fulfilled'', v_summary.quantity, ''order_request'', v_order.id, p_handover_note, auth.uid(), v_k2_instant);\n  end loop;\n\n  update public.orders set order_status = ''Shipped''::order_status_enum where order_request_id = v_order.id;\n  update public.coupon_redemptions set status = ''redeemed'', updated_at = v_k2_instant\n  where order_request_id = v_order.id and status = ''reserved'';\n  update public.order_requests\n  set status = ''fulfilled'', delivery_status = ''handed_to_courier'', fulfilled_at = v_k2_instant, updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''confirmed'', ''fulfilled'', p_handover_note, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n","acl":["postgres=X/postgres","authenticated=X/postgres"],"config":["search_path=public"],"definer":true},{"identity":"public.record_packing_scan_exact_v1(uuid, text, uuid, boolean)","before":"968856dccc70550609fec8c003cced092e10e814f24add9f29ae716bf5459a29","after":"6d07fd6d4efd55606b1a1611ef549fff43586e4edd4a16676d21985f0203741d","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n v_order public.order_requests; v_res public.inventory_reservations;\n v_line public.order_request_items; v_batch public.product_batches; v_scan integer; v_total integer; v_complete boolean;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n if not public.is_staff() or auth.uid() is null then raise exception ''Staff access required'' using errcode=''42501''; end if;\n if p_lot_confirmed is distinct from true then raise exception ''K2_PACKING_LOT_CONFIRMATION_REQUIRED'' using errcode=''23514''; end if;\n select * into v_order from public.order_requests where id=p_order_request_id for update;\n if not found or v_order.status is distinct from ''confirmed'' then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n select * into v_res from public.inventory_reservations where id=p_reservation_id and order_request_id=v_order.id for update;\n if not found or v_res.status is distinct from ''active'' or v_res.packed_quantity is null\n   or v_res.quantity is null or v_res.quantity<=0 or v_res.packed_quantity<0 or v_res.packed_quantity>=v_res.quantity then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select i.* into v_line from public.order_request_items i join public.products p on p.sku=i.sku\n  where i.id=v_res.order_request_item_id and i.order_request_id=v_order.id and i.sku=v_res.sku\n   and (upper(i.sku)=upper(trim(p_scanned_code)) or upper(nullif(p.barcode,''''))=upper(trim(p_scanned_code)));\n if not found then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select * into v_batch from public.product_batches where id=v_res.batch_id and sku=v_res.sku for update;\n if not found or v_batch.inventory_status is distinct from ''available''\n   or v_batch.quantity is null or v_batch.reserved_quantity is null or v_batch.quantity<v_batch.reserved_quantity\n   or v_batch.reserved_quantity<v_res.quantity\n   or v_batch.reserved_quantity<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r where r.batch_id=v_batch.id and r.status=''active'')\n   or not k2_private.lot_is_eligible_v1(v_batch) then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n update public.inventory_reservations set packed_quantity=packed_quantity+1,updated_at=v_k2_instant where id=v_res.id;\n select coalesce(max(scan_number),0)+1 into v_scan from public.packing_scan_events where order_request_item_id=v_line.id;\n insert into public.packing_scan_events(order_request_id,order_request_item_id,reservation_id,batch_id,sku,scanned_code,scan_number,actor_id, created_at)\n  values(v_order.id,v_line.id,v_res.id,v_batch.id,v_line.sku,trim(p_scanned_code),v_scan,auth.uid(), v_k2_instant);\n select coalesce(sum(packed_quantity),0) into v_total from public.inventory_reservations where order_request_item_id=v_line.id and status=''active'';\n if v_total=v_line.quantity then update public.orders set order_status=''Packed'' where order_request_id=v_order.id and sku=v_line.sku and order_status::text=''Pending''; end if;\n select exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   and not exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and i.quantity<>coalesce((select sum(r.packed_quantity) from public.inventory_reservations r where r.order_request_item_id=i.id and r.status=''active''),0)) into v_complete;\n if v_complete then update public.order_requests set delivery_status=''packed'',updated_at=v_k2_instant where id=v_order.id; end if;\n insert into public.order_request_events(order_request_id,from_status,to_status,actor_id,metadata, created_at)\n  values(v_order.id,''confirmed'',''confirmed'',auth.uid(),jsonb_build_object(''event'',''unit_packed'',''sku'',v_line.sku,\n   ''batch_id'',v_batch.id,''reservation_id'',v_res.id,''physical_lot_confirmed'',true,''scan_number'',v_scan), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n return jsonb_build_object(''order_reference'',v_order.public_reference,''sku'',v_line.sku,''product_name'',v_line.product_name,\n  ''packed_quantity'',v_total,''required_quantity'',v_line.quantity,''line_complete'',v_total=v_line.quantity,''order_complete'',v_complete,''batch_id'',v_batch.id);\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.record_packing_scan(uuid, text)","before":"a453b4789e1a28830eb1a6d1217719e8276cbe4c478e0da05b2e67aac4cdccce","after":"7520a48fd358bdc59eed95f8966e1ee0827717cce5f813828ffc324422cf43f3","body":"\ndeclare\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_reservation public.inventory_reservations;\n  v_scan_number integer;\n  v_total_packed integer;\nbegin\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_scanned_code, '''')), '''') is null then raise exception ''Barcode or SKU is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  if v_order.status <> ''confirmed'' then raise exception ''Select a confirmed order before scanning''; end if;\n\n  select i.* into v_line\n  from public.order_request_items i join public.products p on p.sku = i.sku\n  where i.order_request_id = v_order.id\n    and (upper(i.sku) = upper(trim(p_scanned_code)) or upper(coalesce(p.barcode, '''')) = upper(trim(p_scanned_code)))\n  order by i.created_at limit 1;\n  if not found then raise exception ''Scanned item is not part of selected order %'', v_order.public_reference; end if;\n\n  select r.* into v_reservation from public.inventory_reservations r\n  join public.product_batches b on b.id = r.batch_id\n  where r.order_request_item_id = v_line.id and r.status = ''active'' and r.packed_quantity < r.quantity\n  order by coalesce(b.expiry_date, b.best_before_date), r.created_at\n  limit 1 for update of r;\n  if not found then raise exception ''Required quantity is already fully scanned for %'', v_line.product_name; end if;\n\n  update public.inventory_reservations set packed_quantity = packed_quantity + 1, updated_at = now()\n  where id = v_reservation.id returning * into v_reservation;\n  select coalesce(max(scan_number), 0) + 1 into v_scan_number\n  from public.packing_scan_events where order_request_item_id = v_line.id;\n  insert into public.packing_scan_events (\n    order_request_id, order_request_item_id, reservation_id, batch_id, sku, scanned_code, scan_number, actor_id\n  ) values (\n    v_order.id, v_line.id, v_reservation.id, v_reservation.batch_id, v_line.sku,\n    trim(p_scanned_code), v_scan_number, auth.uid()\n  );\n\n  select coalesce(sum(packed_quantity), 0)::integer into v_total_packed\n  from public.inventory_reservations where order_request_item_id = v_line.id and status = ''active'';\n  if v_total_packed = v_line.quantity then\n    update public.orders set order_status = ''Packed''::order_status_enum\n    where order_request_id = v_order.id and sku = v_line.sku and order_status::text = ''Pending'';\n  end if;\n  if not exists (\n    select 1 from public.inventory_reservations r where r.order_request_id = v_order.id\n    and r.status = ''active'' and r.packed_quantity < r.quantity\n  ) then\n    update public.order_requests set delivery_status = ''packed'', updated_at = now() where id = v_order.id;\n  end if;\n\n  insert into public.order_request_events (order_request_id, from_status, to_status, actor_id, metadata)\n  values (v_order.id, ''confirmed'', ''confirmed'', auth.uid(), jsonb_build_object(\n    ''event'', ''unit_packed'', ''sku'', v_line.sku, ''scan_number'', v_scan_number,\n    ''packed_quantity'', v_total_packed, ''required_quantity'', v_line.quantity,\n    ''batch_id'', v_reservation.batch_id\n  ));\n  return jsonb_build_object(\n    ''order_reference'', v_order.public_reference, ''sku'', v_line.sku,\n    ''product_name'', v_line.product_name, ''packed_quantity'', v_total_packed,\n    ''required_quantity'', v_line.quantity, ''line_complete'', v_total_packed = v_line.quantity,\n    ''order_complete'', not exists (\n      select 1 from public.inventory_reservations r where r.order_request_id = v_order.id\n      and r.status = ''active'' and r.packed_quantity < r.quantity\n    )\n  );\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=public"],"definer":true},{"identity":"public.commit_order_request_stock_v1(uuid, text, text)","before":"74482ae26ae813f841cc9bcec89674687aaf088e8642f7c863c4a2bc496ba81c","after":"2351d2533bca8d5a5026afcab54118e1e23d6e70d10074963b11cdd1f4306601","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_res record;\n  v_committed integer := 0;\nbegin\n  v_k2_context:=k2_private.current_category_lot_context_v1();\n  v_k2_instant:=v_k2_context.evaluation_instant;\n  if p_cause is null\n     or p_cause not in (''confirmation'', ''payment_verification'') then\n    raise exception ''Unknown stock commitment cause'';\n  end if;\n\n  -- The order row is locked first, matching cancellation and the sweep, so\n  -- a concurrent cancel serializes here instead of racing the allocations.\n  perform 1 from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if exists(select 1 from public.order_requests o where o.id=p_order_request_id and o.channel_source=''website'')\n    and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=p_order_request_id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n\n  for v_res in\n    select id, sku, quantity, batch_id\n    from public.inventory_reservations\n    where order_request_id = p_order_request_id\n      and status = ''active''\n      and committed_at is null\n    order by sku, batch_id, id\n    for update\n  loop\n    update public.inventory_reservations\n    set committed_at = v_k2_instant,\n        committed_by = auth.uid(),\n        commit_reason = nullif(trim(coalesce(p_reason, '''')), ''''),\n        commit_cause = p_cause\n    where id = v_res.id;\n\n    -- Physical quantity and encumbered counters are intentionally untouched:\n    -- this event deducts ownership, not custody. Handover moves custody.\n    insert into public.inventory_events\n      (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values\n      (v_res.sku, ''MANILA_MAIN'', ''stock_committed'', v_res.quantity,\n       ''order_request'', p_order_request_id,\n       ''Ownership committed at '' || p_cause || '': ''\n         || coalesce(nullif(trim(coalesce(p_reason, '''')), ''''), ''(no reason)'')\n         || ''; batch '' || v_res.batch_id::text,\n       auth.uid(), v_k2_instant);\n\n    v_committed := v_committed + 1;\n  end loop;\n\n  return v_committed;\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.reserve_order_request_lots_v1(uuid, text)","before":"57234309226e3784ea28574ee5136a8c51fead4697bbcbe0f37de095adfa9bb3","after":"8c20627bed4025589a31ef00eb665be8879324e296776745dc45c023f9c8ba63","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_batch public.product_batches;\n  v_balance public.inventory_balances;\n  v_remaining integer;\n  v_take integer;\n  v_held integer := 0;\n  v_existing integer;\nbegin\n  v_k2_context:=k2_private.current_category_lot_context_v1();\n  v_k2_instant:=v_k2_context.evaluation_instant;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n\n  -- Idempotent by design. An order that already holds stock is returned\n  -- untouched, so a retried submission, a staff confirmation following a\n  -- purchase-time hold, and a replayed idempotency key can never stack a second\n  -- claim on the same units.\n  select count(*) into v_existing\n  from public.inventory_reservations\n  where order_request_id = v_order.id and status = ''active'';\n  \n  if v_existing > 0 then\n    perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n      and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n      order by b.sku for update;\n    perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id\n      order by r.sku,r.batch_id,r.id for update;\n    perform 1 from public.product_batches b where b.id in (\n      select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active''\n    ) order by b.sku,b.id for update;\n    if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n      or exists (\n        select 1 from public.order_request_items i where i.order_request_id=v_order.id\n          and i.quantity <> coalesce((select sum(r.quantity) from public.inventory_reservations r\n            join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n            where r.order_request_item_id=i.id and r.order_request_id=v_order.id and r.sku=i.sku\n              and r.status=''active'' and r.quantity>0\n              -- K2_RESERVATION_COMMITTED_COVERAGE_V1\n              and ((r.committed_at is not null and r.committed_by is not null\n                    and r.commit_cause in (''confirmation'',''payment_verification''))\n                or (r.committed_at is null and r.committed_by is null and r.commit_cause is null\n                  and (r.expires_at>v_k2_instant or (r.expires_at is null and v_order.channel_source<>''website''))))\n              and b.inventory_status=''available'' and b.quantity>=b.reserved_quantity\n              and b.reserved_quantity >= (select sum(a.quantity) from public.inventory_reservations a where a.batch_id=b.id and a.status=''active'')\n              and k2_private.lot_is_eligible_v1(b)\n          ),0)\n      ) or exists (\n        select 1 from public.inventory_reservations r\n        left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n        where r.order_request_id=v_order.id and r.status=''active'' and i.id is null\n      ) or exists (\n        select 1 from public.inventory_reservations r\n        left join public.inventory_balances b on b.sku=r.sku and b.location_code=''MANILA_MAIN''\n        where r.order_request_id=v_order.id and r.status=''active''\n          and (b.sku is null or b.reserved < (select sum(a.quantity) from public.inventory_reservations a where a.order_request_id=v_order.id and a.sku=r.sku and a.status=''active''))\n      ) then\n      raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n    end if;\n    return 0;\n  end if;\n  \n\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id)\n    and not exists(select 1 from k2_private.order_delivery_construction_context c where c.order_id=v_order.id\n      and c.backend_pid=pg_catalog.pg_backend_pid() and c.transaction_id=pg_catalog.pg_current_xact_id()) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  -- K2_PURCHASE_BALANCE_LOCK_ORDER_V1\n  -- Conflict checks can acquire locks too, so initialize in the same order.\n  insert into public.inventory_balances (sku, location_code, on_hand)\n  select p.sku, ''MANILA_MAIN'', greatest(coalesce(sum(b.quantity), 0), 0)::integer\n  from public.products p left join public.product_batches b on b.sku=p.sku\n  where p.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n  group by p.sku order by p.sku\n  on conflict (sku, location_code) do nothing;\n  perform 1 from public.inventory_balances b\n  where b.location_code=''MANILA_MAIN''\n    and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n  order by b.sku for update;\n\n  for v_line in\n    select * from public.order_request_items\n    where order_request_id = v_order.id order by sku, created_at, id\n  loop\n\n    -- The balance row is locked before any batch row, in both callers, so two\n    -- concurrent holds on one SKU serialize here rather than racing the lots.\n    select * into v_balance from public.inventory_balances\n    where sku = v_line.sku and location_code = ''MANILA_MAIN'' for update;\n\n    v_remaining := v_line.quantity;\n    for v_batch in\n      select * from public.product_batches b\n      where sku = v_line.sku\n        and inventory_status = ''available''\n        and quantity > reserved_quantity\n        and k2_private.lot_is_eligible_v1(b)\n      order by coalesce(expiry_date, best_before_date), created_at\n      for update\n    loop\n      exit when v_remaining = 0;\n      v_take := least(v_remaining, v_batch.quantity - v_batch.reserved_quantity);\n      update public.product_batches set reserved_quantity = reserved_quantity + v_take, updated_at = v_k2_instant\n      where id = v_batch.id;\n      insert into public.inventory_reservations (\n        order_request_id, order_request_item_id, batch_id, sku, quantity, expires_at, created_at, updated_at\n      ) values (v_order.id, v_line.id, v_batch.id, v_line.sku, v_take,\n        case when v_order.channel_source=''website'' then v_k2_instant+interval ''30 minutes'' end,v_k2_instant,v_k2_instant);\n      v_remaining := v_remaining - v_take;\n    end loop;\n    if v_remaining > 0 then\n      raise exception ''Insufficient sellable lot stock for %. Check expiry, quarantine, and clearance approval.'', v_line.sku\n        using errcode = ''K2STK'';\n    end if;\n\n    if v_balance.reserved + v_line.quantity > v_balance.on_hand then\n      raise exception ''Inventory balance mismatch for %'', v_line.sku using errcode = ''K2STK'';\n    end if;\n    update public.inventory_balances set reserved = reserved + v_line.quantity, updated_at = v_k2_instant\n    where sku = v_line.sku and location_code = ''MANILA_MAIN'';\n\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set\n      stock_available = (\n        select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n        where b.sku = v_line.sku and b.inventory_status = ''available''\n          and k2_private.lot_is_eligible_v1(b)\n      )\n    where sku = v_line.sku;\n\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_line.sku, ''MANILA_MAIN'', ''reserved'', v_line.quantity, ''order_request'', v_order.id, p_reason, auth.uid(), v_k2_instant);\n\n    v_held := v_held + 1;\n  end loop;\n\n  return v_held;\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=public"],"definer":true},{"identity":"public.submit_order_payment_receipt_v1(uuid, text, text, text, text, uuid)","before":"054c8ee2bae965be8c957fb71fcf59fdc3f8b094cb61abfc42f98b010bcb3c78","after":"578d7ec4c0fceda02cf3d78531eaeb42e6573a13ed3194bfc43fb5a12ef0f8c8","body":"\ndeclare\n  v_order public.order_requests;\n  v_conversation_id uuid;\n  v_bytes bytea;\n  v_sha text;\n  v_id uuid;\n  v_ref text := trim(coalesce(p_payment_reference,''''));\nbegin\n  if p_order_id is null or p_order_key is null or length(p_order_key) not between 32 and 100\n     or p_request_key is null then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_ACCESS_REQUIRED'');\n  end if;\n  select * into v_order from public.order_requests\n  where id=p_order_id and idempotency_key=p_order_key for update;\n  if not found then return jsonb_build_object(''ok'', false, ''error'', ''ORDER_ACCESS_REQUIRED''); end if;\n\n  select id into v_id from k2_private.order_payment_receipts\n  where order_id=p_order_id and request_key=p_request_key;\n  if v_id is not null then return jsonb_build_object(''ok'', true, ''receipt_id'', v_id, ''replayed'', true); end if;\n\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    return jsonb_build_object(''ok'',false,''error'',''K2_DELIVERY_REVIEW_REQUIRED'');\n  end if;\n  if v_order.payment_status not in (''awaiting_instructions'',''evidence_submitted'',''failed'')\n    or v_order.shipping_quote_status not in (''platform_charged'',''customer_confirmed'',''waived'')\n    or v_order.total_amount is null or v_order.total_amount<0 then\n    return jsonb_build_object(''ok'',false,''error'',''ORDER_RECEIPT_CLOSED'');\n  end if;\n  if v_order.status not in (''submitted'',''confirmed'') or v_order.payment_status in (''verified'',''refunded'') then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_RECEIPT_CLOSED'');\n  end if;\n  if length(v_ref) not between 1 and 100\n     or p_media_type is null or p_media_type not in (''image/png'',''image/jpeg'',''application/pdf'')\n     or p_base64 is null or length(p_base64) not between 24 and 4194304 then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_INVALID'');\n  end if;\n  if (select count(*) from k2_private.order_payment_receipts where order_id=p_order_id) >= 3 then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_LIMIT_REACHED'');\n  end if;\n\n  begin\n    v_bytes := decode(p_base64, ''base64'');\n  exception when invalid_parameter_value or data_exception then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_INVALID'');\n  end;\n  if octet_length(v_bytes) not between 16 and 3145728\n     or not (\n       (p_media_type=''image/png'' and substring(v_bytes from 1 for 8)=decode(''89504e470d0a1a0a'',''hex'')) or\n       (p_media_type=''image/jpeg'' and substring(v_bytes from 1 for 3)=decode(''ffd8ff'',''hex'')) or\n       (p_media_type=''application/pdf'' and substring(v_bytes from 1 for 5)=decode(''255044462d'',''hex''))\n     ) then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_INVALID'');\n  end if;\n  v_sha := encode(extensions.digest(v_bytes,''sha256''),''hex'');\n  select id into v_id from k2_private.order_payment_receipts\n  where order_id=p_order_id and sha256=v_sha;\n  if v_id is not null then return jsonb_build_object(''ok'', true, ''receipt_id'', v_id, ''replayed'', true); end if;\n\n  select id into v_conversation_id from public.conversations\n  where source_kind=''order_request'' and source_id=p_order_id;\n  if v_conversation_id is null then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_CONVERSATION_UNAVAILABLE'');\n  end if;\n\n  insert into k2_private.order_payment_receipts\n    (order_id, request_key, payment_reference, media_type, byte_size, sha256, contents)\n  values (p_order_id,p_request_key,v_ref,p_media_type,octet_length(v_bytes),v_sha,v_bytes)\n  returning id into v_id;\n  insert into public.messages(conversation_id,sender_type,content,is_draft,delivery_status,direction)\n  values (v_conversation_id,''Customer'',\n    ''Payment receipt uploaded for order '' || v_order.public_reference || ''. Reference: '' || v_ref ||\n      ''. Staff must review this proof and confirm funds separately. Receipt ID: '' || v_id::text,\n    false,''received'',''inbound'');\n  update public.conversations set unread_count=coalesce(unread_count,0)+1,\n    last_inbound_at=now(), last_message_at=now(), response_due_at=now()+interval ''4 hours'',\n    updated_at=now() where id=v_conversation_id;\n  return jsonb_build_object(''ok'', true, ''receipt_id'', v_id, ''replayed'', false);\nend;\n","acl":null,"config":["search_path=\"\""],"definer":true}]'::jsonb)
  as x(identity text,before text,after text,body text,acl text[],config text[],definer boolean) loop
  select * into b from pg_proc where oid=to_regprocedure(t.identity);
  if not found or pg_get_userbyid(b.proowner)<>'postgres' or b.proacl::text[] is distinct from t.acl
   or b.proconfig is distinct from t.config or b.prosecdef is distinct from t.definer then raise exception 'K2_LEGACY_WRITER_AUTHORITY_DRIFT';end if;
  v_hash:=encode(extensions.digest(convert_to(replace(b.prosrc,chr(13)||chr(10),chr(10)),'UTF8'),'sha256'),'hex');
  v_before:=v_before and v_hash=t.before;v_after:=v_after and v_hash=t.after;
 end loop;
 if not v_before and not v_after then raise exception 'K2_LEGACY_WRITER_BODY_DRIFT';end if;
 if v_after then return;end if;
 for t in select * from jsonb_to_recordset('[{"identity":"public.confirm_order_request(uuid, text)","before":"00eeb9159ab64fec2ac935d5ce6bd9a5cc07c6a4b86d3a50d02ae69f8d86b0ed","after":"1bb69c883e85cd97c5b4a4cf900bfa5a35d5afdc19f396bcc048d3fa4ed35475","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_coupon public.coupons;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''confirmed'' then return v_order; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  if v_order.status <> ''submitted'' then raise exception ''Only submitted requests can be confirmed''; end if;\n\n  perform 1 from public.coupons where id=v_order.coupon_id for update;\n  insert into public.inventory_balances(sku,location_code,on_hand,reserved)\n  select p.sku,''MANILA_MAIN'',coalesce(sum(b.quantity),0)::integer,coalesce(sum(b.reserved_quantity),0)::integer\n  from public.products p left join public.product_batches b on b.sku=p.sku\n  where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n  group by p.sku order by p.sku on conflict(sku,location_code) do nothing;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  if v_order.coupon_id is not null then\n    select * into v_coupon from public.coupons where id = v_order.coupon_id for update;\n    if not found or not v_coupon.is_active or v_coupon.archived_at is not null\n       or v_coupon.starts_at > v_k2_instant or (v_coupon.ends_at is not null and v_coupon.ends_at <= v_k2_instant)\n       or (v_coupon.max_redemptions is not null and v_coupon.redemption_count >= v_coupon.max_redemptions) then\n      raise exception ''The coupon is no longer available'';\n    end if;\n    update public.coupons set redemption_count = redemption_count + 1 where id = v_coupon.id;\n    insert into public.coupon_redemptions (coupon_id, order_request_id, discount_amount)\n    values (v_coupon.id, v_order.id, v_order.discount_amount);\n  end if;\n\n  perform public.reserve_order_request_lots_v1(v_order.id, p_reason);\n\n  for v_line in select * from public.order_request_items where order_request_id = v_order.id order by created_at\n  loop\n    insert into public.orders (\n      sku, quantity, channel_source, fulfillment_method, order_status,\n      payment_status, customer_name, customer_email, total_amount, order_request_id\n    ) values (\n      v_line.sku, v_line.quantity,\n      case v_order.channel_source\n        when ''shopee'' then ''shopee''::channel_type\n        when ''lazada'' then ''lazada''::channel_type\n        when ''tiktok'' then ''tiktok''::channel_type\n        else ''website_retail''::channel_type end,\n      v_order.fulfillment_method, ''Pending''::order_status_enum, ''Unpaid''::payment_status_enum,\n      v_order.customer_name, v_order.customer_email, v_line.line_total, v_order.id\n    );\n  end loop;\n\n  update public.order_requests\n  set status = ''confirmed'', confirmed_by = auth.uid(), confirmed_at = v_k2_instant,\n      delivery_status = case when shipping_quote_status in (''platform_charged'', ''customer_confirmed'', ''waived'') then ''ready_to_pack'' else delivery_status end,\n      updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n\n  -- Owned stock leaves the sellable pool here, once. The early return above\n  -- keeps a replayed confirmation from deducting again, and the helper\n  -- itself skips already-committed allocations, so both guards agree.\n  perform public.commit_order_request_stock_v1(v_order.id, ''confirmation'', p_reason);\n\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''submitted'', ''confirmed'', p_reason, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n","acl":null,"config":["search_path=public"],"definer":true},{"identity":"public.fulfill_order_request(uuid, text)","before":"7904bf79c0965c514981d7b415eae620d26a31e1098ac7a615f4b26604c2eb2a","after":"52213a6f3f278b694f3f6bb22e21d81da080b6af8fa56052392fdd2eef8caea8","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_res public.inventory_reservations;\n  v_summary record;\n  v_balance public.inventory_balances; v_handover_reservation_ids uuid[];\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_handover_note, '''')), '''') is null then raise exception ''Courier or handover note is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status = ''fulfilled'' then return v_order; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  if v_order.status <> ''confirmed'' then raise exception ''Order request is not confirmed''; end if;\n  if v_order.payment_status is distinct from ''verified'' then raise exception ''Payment must be explicitly verified before fulfillment''; end if;\n  if coalesce(v_order.shipping_quote_status,'''') not in (''platform_charged'', ''customer_confirmed'', ''waived'') then\n    raise exception ''Delivery charge or customer confirmation is still pending'';\n  end if;\n\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n  -- Lock all affected rows before validating, in the prepared release order.\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n   and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id)\n   order by b.sku for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id\n   order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.id in(\n   select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active'')\n   order by b.sku,b.id for update;\n  select array_agg(id) into v_handover_reservation_ids from public.inventory_reservations\n   where order_request_id=v_order.id and status=''active'';\n  if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   or exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and (i.quantity is null or i.quantity<=0 or i.quantity<>coalesce((select sum(r.quantity)\n      from public.inventory_reservations r where r.order_request_id=v_order.id\n      and r.order_request_item_id=i.id and r.sku=i.sku and r.status=''active''\n      and r.packed_quantity=r.quantity),0)))\n   or exists(select 1 from public.inventory_reservations r\n    left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n    left join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n    left join public.inventory_balances bal on bal.sku=r.sku and bal.location_code=''MANILA_MAIN''\n    where r.id=any(v_handover_reservation_ids) and (i.id is null or b.id is null or bal.sku is null\n     or r.quantity<=0 or r.packed_quantity is distinct from r.quantity\n     or b.inventory_status is distinct from ''available''\n     or b.quantity<b.reserved_quantity or b.reserved_quantity<(select sum(x.quantity) from public.inventory_reservations x where x.batch_id=b.id and x.status=''active'')\n     or bal.on_hand<bal.reserved or bal.reserved<(select sum(x.quantity) from public.inventory_reservations x where x.order_request_id=v_order.id and x.sku=r.sku and x.status=''active'')\n     or not k2_private.lot_is_eligible_v1(b))) then\n   raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  -- K2_HANDOVER_STOCK_COMMITMENT_V1\n  -- Locked exact allocations must already carry attributable ownership evidence.\n  -- Never backfill a historical sale or deduct ownership for the first time at dispatch.\n  if exists(select 1 from public.inventory_reservations r where r.id=any(v_handover_reservation_ids)\n    and (r.committed_at is null or r.committed_by is null\n      or not coalesce(r.commit_cause in (''confirmation'',''payment_verification''),false))) then\n    raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n  end if;\n  if exists (select 1 from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' and packed_quantity <> quantity) then\n    raise exception ''Every required unit must be scanned before fulfillment'';\n  end if;\n  if exists (\n    select 1 from public.inventory_reservations r join public.product_batches b on b.id = r.batch_id\n    where r.order_request_id = v_order.id and r.status = ''active''\n      and not k2_private.lot_is_eligible_v1(b)\n  ) then raise exception ''A reserved lot is no longer sellable; resolve the inventory exception first''; end if;\n\n  for v_res in select * from public.inventory_reservations where order_request_id = v_order.id and status = ''active'' for update\n  loop\n    update public.product_batches\n    set quantity = quantity - v_res.quantity,\n        reserved_quantity = reserved_quantity - v_res.quantity,\n        inventory_status = case when quantity - v_res.quantity = 0 then ''depleted'' else inventory_status end,\n        updated_at = v_k2_instant\n    where id = v_res.batch_id and quantity >= v_res.quantity and reserved_quantity >= v_res.quantity;\n    if not found then raise exception ''Exact lot quantity mismatch for %'', v_res.sku; end if;\n    update public.inventory_reservations set status = ''fulfilled'', updated_at = v_k2_instant where id = v_res.id;\n  end loop;\n\n  for v_summary in select sku, sum(quantity)::integer quantity\n    from public.inventory_reservations where id = any(v_handover_reservation_ids) group by sku\n  loop\n    update public.inventory_balances\n    set on_hand = on_hand - v_summary.quantity, reserved = reserved - v_summary.quantity, updated_at = v_k2_instant\n    where sku = v_summary.sku and location_code = ''MANILA_MAIN''\n      and on_hand >= v_summary.quantity and reserved >= v_summary.quantity;\n    if not found then raise exception ''Inventory balance mismatch for %'', v_summary.sku; end if;\n    select * into v_balance from public.inventory_balances where sku = v_summary.sku and location_code = ''MANILA_MAIN'';\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set stock_available = (\n      select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n      where b.sku = v_summary.sku and b.inventory_status = ''available''\n        and k2_private.lot_is_eligible_v1(b)\n    ) where sku = v_summary.sku;\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_summary.sku, ''MANILA_MAIN'', ''fulfilled'', v_summary.quantity, ''order_request'', v_order.id, p_handover_note, auth.uid(), v_k2_instant);\n  end loop;\n\n  update public.orders set order_status = ''Shipped''::order_status_enum where order_request_id = v_order.id;\n  update public.coupon_redemptions set status = ''redeemed'', updated_at = v_k2_instant\n  where order_request_id = v_order.id and status = ''reserved'';\n  update public.order_requests\n  set status = ''fulfilled'', delivery_status = ''handed_to_courier'', fulfilled_at = v_k2_instant, updated_at = v_k2_instant\n  where id = v_order.id returning * into v_order;\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, created_at)\n  values (v_order.id, ''confirmed'', ''fulfilled'', p_handover_note, auth.uid(), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n  return v_order;\nend;\n","acl":["postgres=X/postgres","authenticated=X/postgres"],"config":["search_path=public"],"definer":true},{"identity":"public.record_packing_scan_exact_v1(uuid, text, uuid, boolean)","before":"968856dccc70550609fec8c003cced092e10e814f24add9f29ae716bf5459a29","after":"6d07fd6d4efd55606b1a1611ef549fff43586e4edd4a16676d21985f0203741d","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n v_order public.order_requests; v_res public.inventory_reservations;\n v_line public.order_request_items; v_batch public.product_batches; v_scan integer; v_total integer; v_complete boolean;\nbegin\n  perform k2_private.lock_category_policy_v1(false);\n if not public.is_staff() or auth.uid() is null then raise exception ''Staff access required'' using errcode=''42501''; end if;\n if p_lot_confirmed is distinct from true then raise exception ''K2_PACKING_LOT_CONFIRMATION_REQUIRED'' using errcode=''23514''; end if;\n select * into v_order from public.order_requests where id=p_order_request_id for update;\n if not found or v_order.status is distinct from ''confirmed'' then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  perform 1 from public.order_request_items where order_request_id=v_order.id order by sku,id for update;\n  perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN'' and b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku for update;\n  perform 1 from public.products p where p.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by p.sku,p.id for update;\n  perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id order by r.sku,r.batch_id,r.id for update;\n  perform 1 from public.product_batches b where b.sku in(select sku from public.order_request_items where order_request_id=v_order.id) order by b.sku,b.id for update;\n  if exists(select 1 from k2_private.category_lot_command_context\n    where backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id()) then\n    v_k2_context:=k2_private.current_category_lot_context_v1();\n    v_k2_instant:=v_k2_context.evaluation_instant;\n  else\n    select maximum_depth into v_k2_depth from k2_private.category_policy_command_config where singleton;\n    if v_k2_depth is null or v_k2_depth<1 then\n      raise exception using errcode=''55000'',message=''K2_CATEGORY_POLICY_NOT_CONFIGURED'';\n    end if;\n    v_k2_instant:=k2_private.start_category_lot_context_v1(v_k2_depth);\n    v_k2_owned:=true;\n  end if;\n select * into v_res from public.inventory_reservations where id=p_reservation_id and order_request_id=v_order.id for update;\n if not found or v_res.status is distinct from ''active'' or v_res.packed_quantity is null\n   or v_res.quantity is null or v_res.quantity<=0 or v_res.packed_quantity<0 or v_res.packed_quantity>=v_res.quantity then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select i.* into v_line from public.order_request_items i join public.products p on p.sku=i.sku\n  where i.id=v_res.order_request_item_id and i.order_request_id=v_order.id and i.sku=v_res.sku\n   and (upper(i.sku)=upper(trim(p_scanned_code)) or upper(nullif(p.barcode,''''))=upper(trim(p_scanned_code)));\n if not found then raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n select * into v_batch from public.product_batches where id=v_res.batch_id and sku=v_res.sku for update;\n if not found or v_batch.inventory_status is distinct from ''available''\n   or v_batch.quantity is null or v_batch.reserved_quantity is null or v_batch.quantity<v_batch.reserved_quantity\n   or v_batch.reserved_quantity<v_res.quantity\n   or v_batch.reserved_quantity<(select coalesce(sum(r.quantity),0) from public.inventory_reservations r where r.batch_id=v_batch.id and r.status=''active'')\n   or not k2_private.lot_is_eligible_v1(v_batch) then\n  raise exception ''K2_PACKING_ALLOCATION_INVALID'' using errcode=''23514''; end if;\n update public.inventory_reservations set packed_quantity=packed_quantity+1,updated_at=v_k2_instant where id=v_res.id;\n select coalesce(max(scan_number),0)+1 into v_scan from public.packing_scan_events where order_request_item_id=v_line.id;\n insert into public.packing_scan_events(order_request_id,order_request_item_id,reservation_id,batch_id,sku,scanned_code,scan_number,actor_id, created_at)\n  values(v_order.id,v_line.id,v_res.id,v_batch.id,v_line.sku,trim(p_scanned_code),v_scan,auth.uid(), v_k2_instant);\n select coalesce(sum(packed_quantity),0) into v_total from public.inventory_reservations where order_request_item_id=v_line.id and status=''active'';\n if v_total=v_line.quantity then update public.orders set order_status=''Packed'' where order_request_id=v_order.id and sku=v_line.sku and order_status::text=''Pending''; end if;\n select exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n   and not exists(select 1 from public.order_request_items i where i.order_request_id=v_order.id\n    and i.quantity<>coalesce((select sum(r.packed_quantity) from public.inventory_reservations r where r.order_request_item_id=i.id and r.status=''active''),0)) into v_complete;\n if v_complete then update public.order_requests set delivery_status=''packed'',updated_at=v_k2_instant where id=v_order.id; end if;\n insert into public.order_request_events(order_request_id,from_status,to_status,actor_id,metadata, created_at)\n  values(v_order.id,''confirmed'',''confirmed'',auth.uid(),jsonb_build_object(''event'',''unit_packed'',''sku'',v_line.sku,\n   ''batch_id'',v_batch.id,''reservation_id'',v_res.id,''physical_lot_confirmed'',true,''scan_number'',v_scan), v_k2_instant);\n  if v_k2_owned then perform k2_private.clear_category_lot_context_v1();end if;\n return jsonb_build_object(''order_reference'',v_order.public_reference,''sku'',v_line.sku,''product_name'',v_line.product_name,\n  ''packed_quantity'',v_total,''required_quantity'',v_line.quantity,''line_complete'',v_total=v_line.quantity,''order_complete'',v_complete,''batch_id'',v_batch.id);\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.record_packing_scan(uuid, text)","before":"a453b4789e1a28830eb1a6d1217719e8276cbe4c478e0da05b2e67aac4cdccce","after":"7520a48fd358bdc59eed95f8966e1ee0827717cce5f813828ffc324422cf43f3","body":"\ndeclare\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_reservation public.inventory_reservations;\n  v_scan_number integer;\n  v_total_packed integer;\nbegin\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if nullif(trim(coalesce(p_scanned_code, '''')), '''') is null then raise exception ''Barcode or SKU is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  if v_order.status <> ''confirmed'' then raise exception ''Select a confirmed order before scanning''; end if;\n\n  select i.* into v_line\n  from public.order_request_items i join public.products p on p.sku = i.sku\n  where i.order_request_id = v_order.id\n    and (upper(i.sku) = upper(trim(p_scanned_code)) or upper(coalesce(p.barcode, '''')) = upper(trim(p_scanned_code)))\n  order by i.created_at limit 1;\n  if not found then raise exception ''Scanned item is not part of selected order %'', v_order.public_reference; end if;\n\n  select r.* into v_reservation from public.inventory_reservations r\n  join public.product_batches b on b.id = r.batch_id\n  where r.order_request_item_id = v_line.id and r.status = ''active'' and r.packed_quantity < r.quantity\n  order by coalesce(b.expiry_date, b.best_before_date), r.created_at\n  limit 1 for update of r;\n  if not found then raise exception ''Required quantity is already fully scanned for %'', v_line.product_name; end if;\n\n  update public.inventory_reservations set packed_quantity = packed_quantity + 1, updated_at = now()\n  where id = v_reservation.id returning * into v_reservation;\n  select coalesce(max(scan_number), 0) + 1 into v_scan_number\n  from public.packing_scan_events where order_request_item_id = v_line.id;\n  insert into public.packing_scan_events (\n    order_request_id, order_request_item_id, reservation_id, batch_id, sku, scanned_code, scan_number, actor_id\n  ) values (\n    v_order.id, v_line.id, v_reservation.id, v_reservation.batch_id, v_line.sku,\n    trim(p_scanned_code), v_scan_number, auth.uid()\n  );\n\n  select coalesce(sum(packed_quantity), 0)::integer into v_total_packed\n  from public.inventory_reservations where order_request_item_id = v_line.id and status = ''active'';\n  if v_total_packed = v_line.quantity then\n    update public.orders set order_status = ''Packed''::order_status_enum\n    where order_request_id = v_order.id and sku = v_line.sku and order_status::text = ''Pending'';\n  end if;\n  if not exists (\n    select 1 from public.inventory_reservations r where r.order_request_id = v_order.id\n    and r.status = ''active'' and r.packed_quantity < r.quantity\n  ) then\n    update public.order_requests set delivery_status = ''packed'', updated_at = now() where id = v_order.id;\n  end if;\n\n  insert into public.order_request_events (order_request_id, from_status, to_status, actor_id, metadata)\n  values (v_order.id, ''confirmed'', ''confirmed'', auth.uid(), jsonb_build_object(\n    ''event'', ''unit_packed'', ''sku'', v_line.sku, ''scan_number'', v_scan_number,\n    ''packed_quantity'', v_total_packed, ''required_quantity'', v_line.quantity,\n    ''batch_id'', v_reservation.batch_id\n  ));\n  return jsonb_build_object(\n    ''order_reference'', v_order.public_reference, ''sku'', v_line.sku,\n    ''product_name'', v_line.product_name, ''packed_quantity'', v_total_packed,\n    ''required_quantity'', v_line.quantity, ''line_complete'', v_total_packed = v_line.quantity,\n    ''order_complete'', not exists (\n      select 1 from public.inventory_reservations r where r.order_request_id = v_order.id\n      and r.status = ''active'' and r.packed_quantity < r.quantity\n    )\n  );\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=public"],"definer":true},{"identity":"public.commit_order_request_stock_v1(uuid, text, text)","before":"74482ae26ae813f841cc9bcec89674687aaf088e8642f7c863c4a2bc496ba81c","after":"2351d2533bca8d5a5026afcab54118e1e23d6e70d10074963b11cdd1f4306601","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_res record;\n  v_committed integer := 0;\nbegin\n  v_k2_context:=k2_private.current_category_lot_context_v1();\n  v_k2_instant:=v_k2_context.evaluation_instant;\n  if p_cause is null\n     or p_cause not in (''confirmation'', ''payment_verification'') then\n    raise exception ''Unknown stock commitment cause'';\n  end if;\n\n  -- The order row is locked first, matching cancellation and the sweep, so\n  -- a concurrent cancel serializes here instead of racing the allocations.\n  perform 1 from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if exists(select 1 from public.order_requests o where o.id=p_order_request_id and o.channel_source=''website'')\n    and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=p_order_request_id) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n\n  for v_res in\n    select id, sku, quantity, batch_id\n    from public.inventory_reservations\n    where order_request_id = p_order_request_id\n      and status = ''active''\n      and committed_at is null\n    order by sku, batch_id, id\n    for update\n  loop\n    update public.inventory_reservations\n    set committed_at = v_k2_instant,\n        committed_by = auth.uid(),\n        commit_reason = nullif(trim(coalesce(p_reason, '''')), ''''),\n        commit_cause = p_cause\n    where id = v_res.id;\n\n    -- Physical quantity and encumbered counters are intentionally untouched:\n    -- this event deducts ownership, not custody. Handover moves custody.\n    insert into public.inventory_events\n      (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values\n      (v_res.sku, ''MANILA_MAIN'', ''stock_committed'', v_res.quantity,\n       ''order_request'', p_order_request_id,\n       ''Ownership committed at '' || p_cause || '': ''\n         || coalesce(nullif(trim(coalesce(p_reason, '''')), ''''), ''(no reason)'')\n         || ''; batch '' || v_res.batch_id::text,\n       auth.uid(), v_k2_instant);\n\n    v_committed := v_committed + 1;\n  end loop;\n\n  return v_committed;\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.reserve_order_request_lots_v1(uuid, text)","before":"57234309226e3784ea28574ee5136a8c51fead4697bbcbe0f37de095adfa9bb3","after":"8c20627bed4025589a31ef00eb665be8879324e296776745dc45c023f9c8ba63","body":"\ndeclare\n  v_k2_context k2_private.category_lot_command_context;\n  v_k2_owned boolean:=false;\n  v_k2_depth integer;\n  v_k2_instant timestamptz;\n\n  v_order public.order_requests;\n  v_line public.order_request_items;\n  v_batch public.product_batches;\n  v_balance public.inventory_balances;\n  v_remaining integer;\n  v_take integer;\n  v_held integer := 0;\n  v_existing integer;\nbegin\n  v_k2_context:=k2_private.current_category_lot_context_v1();\n  v_k2_instant:=v_k2_context.evaluation_instant;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n\n  -- Idempotent by design. An order that already holds stock is returned\n  -- untouched, so a retried submission, a staff confirmation following a\n  -- purchase-time hold, and a replayed idempotency key can never stack a second\n  -- claim on the same units.\n  select count(*) into v_existing\n  from public.inventory_reservations\n  where order_request_id = v_order.id and status = ''active'';\n  \n  if v_existing > 0 then\n    perform 1 from public.inventory_balances b where b.location_code=''MANILA_MAIN''\n      and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n      order by b.sku for update;\n    perform 1 from public.inventory_reservations r where r.order_request_id=v_order.id\n      order by r.sku,r.batch_id,r.id for update;\n    perform 1 from public.product_batches b where b.id in (\n      select batch_id from public.inventory_reservations where order_request_id=v_order.id and status=''active''\n    ) order by b.sku,b.id for update;\n    if not exists(select 1 from public.order_request_items where order_request_id=v_order.id)\n      or exists (\n        select 1 from public.order_request_items i where i.order_request_id=v_order.id\n          and i.quantity <> coalesce((select sum(r.quantity) from public.inventory_reservations r\n            join public.product_batches b on b.id=r.batch_id and b.sku=r.sku\n            where r.order_request_item_id=i.id and r.order_request_id=v_order.id and r.sku=i.sku\n              and r.status=''active'' and r.quantity>0\n              -- K2_RESERVATION_COMMITTED_COVERAGE_V1\n              and ((r.committed_at is not null and r.committed_by is not null\n                    and r.commit_cause in (''confirmation'',''payment_verification''))\n                or (r.committed_at is null and r.committed_by is null and r.commit_cause is null\n                  and (r.expires_at>v_k2_instant or (r.expires_at is null and v_order.channel_source<>''website''))))\n              and b.inventory_status=''available'' and b.quantity>=b.reserved_quantity\n              and b.reserved_quantity >= (select sum(a.quantity) from public.inventory_reservations a where a.batch_id=b.id and a.status=''active'')\n              and k2_private.lot_is_eligible_v1(b)\n          ),0)\n      ) or exists (\n        select 1 from public.inventory_reservations r\n        left join public.order_request_items i on i.id=r.order_request_item_id and i.order_request_id=v_order.id and i.sku=r.sku\n        where r.order_request_id=v_order.id and r.status=''active'' and i.id is null\n      ) or exists (\n        select 1 from public.inventory_reservations r\n        left join public.inventory_balances b on b.sku=r.sku and b.location_code=''MANILA_MAIN''\n        where r.order_request_id=v_order.id and r.status=''active''\n          and (b.sku is null or b.reserved < (select sum(a.quantity) from public.inventory_reservations a where a.order_request_id=v_order.id and a.sku=r.sku and a.status=''active''))\n      ) then\n      raise exception ''K2_RESERVATION_RECONCILIATION_REQUIRED'' using errcode=''23514'';\n    end if;\n    return 0;\n  end if;\n  \n\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id)\n    and not exists(select 1 from k2_private.order_delivery_construction_context c where c.order_id=v_order.id\n      and c.backend_pid=pg_catalog.pg_backend_pid() and c.transaction_id=pg_catalog.pg_current_xact_id()) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  -- K2_PURCHASE_BALANCE_LOCK_ORDER_V1\n  -- Conflict checks can acquire locks too, so initialize in the same order.\n  insert into public.inventory_balances (sku, location_code, on_hand)\n  select p.sku, ''MANILA_MAIN'', greatest(coalesce(sum(b.quantity), 0), 0)::integer\n  from public.products p left join public.product_batches b on b.sku=p.sku\n  where p.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n  group by p.sku order by p.sku\n  on conflict (sku, location_code) do nothing;\n  perform 1 from public.inventory_balances b\n  where b.location_code=''MANILA_MAIN''\n    and b.sku in (select sku from public.order_request_items where order_request_id=v_order.id)\n  order by b.sku for update;\n\n  for v_line in\n    select * from public.order_request_items\n    where order_request_id = v_order.id order by sku, created_at, id\n  loop\n\n    -- The balance row is locked before any batch row, in both callers, so two\n    -- concurrent holds on one SKU serialize here rather than racing the lots.\n    select * into v_balance from public.inventory_balances\n    where sku = v_line.sku and location_code = ''MANILA_MAIN'' for update;\n\n    v_remaining := v_line.quantity;\n    for v_batch in\n      select * from public.product_batches b\n      where sku = v_line.sku\n        and inventory_status = ''available''\n        and quantity > reserved_quantity\n        and k2_private.lot_is_eligible_v1(b)\n      order by coalesce(expiry_date, best_before_date), created_at\n      for update\n    loop\n      exit when v_remaining = 0;\n      v_take := least(v_remaining, v_batch.quantity - v_batch.reserved_quantity);\n      update public.product_batches set reserved_quantity = reserved_quantity + v_take, updated_at = v_k2_instant\n      where id = v_batch.id;\n      insert into public.inventory_reservations (\n        order_request_id, order_request_item_id, batch_id, sku, quantity, expires_at, created_at, updated_at\n      ) values (v_order.id, v_line.id, v_batch.id, v_line.sku, v_take,\n        case when v_order.channel_source=''website'' then v_k2_instant+interval ''30 minutes'' end,v_k2_instant,v_k2_instant);\n      v_remaining := v_remaining - v_take;\n    end loop;\n    if v_remaining > 0 then\n      raise exception ''Insufficient sellable lot stock for %. Check expiry, quarantine, and clearance approval.'', v_line.sku\n        using errcode = ''K2STK'';\n    end if;\n\n    if v_balance.reserved + v_line.quantity > v_balance.on_hand then\n      raise exception ''Inventory balance mismatch for %'', v_line.sku using errcode = ''K2STK'';\n    end if;\n    update public.inventory_balances set reserved = reserved + v_line.quantity, updated_at = v_k2_instant\n    where sku = v_line.sku and location_code = ''MANILA_MAIN'';\n\n    perform set_config(''k2.allow_stock_write'', ''on'', true);\n    update public.products set\n      stock_available = (\n        select coalesce(sum(b.quantity - b.reserved_quantity), 0)::integer from public.product_batches b\n        where b.sku = v_line.sku and b.inventory_status = ''available''\n          and k2_private.lot_is_eligible_v1(b)\n      )\n    where sku = v_line.sku;\n\n    insert into public.inventory_events (sku, location_code, event_type, quantity, reference_type, reference_id, reason, actor_id, created_at)\n    values (v_line.sku, ''MANILA_MAIN'', ''reserved'', v_line.quantity, ''order_request'', v_order.id, p_reason, auth.uid(), v_k2_instant);\n\n    v_held := v_held + 1;\n  end loop;\n\n  return v_held;\nend;\n","acl":["postgres=X/postgres"],"config":["search_path=public"],"definer":true},{"identity":"public.submit_order_payment_receipt_v1(uuid, text, text, text, text, uuid)","before":"054c8ee2bae965be8c957fb71fcf59fdc3f8b094cb61abfc42f98b010bcb3c78","after":"578d7ec4c0fceda02cf3d78531eaeb42e6573a13ed3194bfc43fb5a12ef0f8c8","body":"\ndeclare\n  v_order public.order_requests;\n  v_conversation_id uuid;\n  v_bytes bytea;\n  v_sha text;\n  v_id uuid;\n  v_ref text := trim(coalesce(p_payment_reference,''''));\nbegin\n  if p_order_id is null or p_order_key is null or length(p_order_key) not between 32 and 100\n     or p_request_key is null then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_ACCESS_REQUIRED'');\n  end if;\n  select * into v_order from public.order_requests\n  where id=p_order_id and idempotency_key=p_order_key for update;\n  if not found then return jsonb_build_object(''ok'', false, ''error'', ''ORDER_ACCESS_REQUIRED''); end if;\n\n  select id into v_id from k2_private.order_payment_receipts\n  where order_id=p_order_id and request_key=p_request_key;\n  if v_id is not null then return jsonb_build_object(''ok'', true, ''receipt_id'', v_id, ''replayed'', true); end if;\n\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    return jsonb_build_object(''ok'',false,''error'',''K2_DELIVERY_REVIEW_REQUIRED'');\n  end if;\n  if v_order.payment_status not in (''awaiting_instructions'',''evidence_submitted'',''failed'')\n    or v_order.shipping_quote_status not in (''platform_charged'',''customer_confirmed'',''waived'')\n    or v_order.total_amount is null or v_order.total_amount<0 then\n    return jsonb_build_object(''ok'',false,''error'',''ORDER_RECEIPT_CLOSED'');\n  end if;\n  if v_order.status not in (''submitted'',''confirmed'') or v_order.payment_status in (''verified'',''refunded'') then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_RECEIPT_CLOSED'');\n  end if;\n  if length(v_ref) not between 1 and 100\n     or p_media_type is null or p_media_type not in (''image/png'',''image/jpeg'',''application/pdf'')\n     or p_base64 is null or length(p_base64) not between 24 and 4194304 then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_INVALID'');\n  end if;\n  if (select count(*) from k2_private.order_payment_receipts where order_id=p_order_id) >= 3 then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_LIMIT_REACHED'');\n  end if;\n\n  begin\n    v_bytes := decode(p_base64, ''base64'');\n  exception when invalid_parameter_value or data_exception then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_INVALID'');\n  end;\n  if octet_length(v_bytes) not between 16 and 3145728\n     or not (\n       (p_media_type=''image/png'' and substring(v_bytes from 1 for 8)=decode(''89504e470d0a1a0a'',''hex'')) or\n       (p_media_type=''image/jpeg'' and substring(v_bytes from 1 for 3)=decode(''ffd8ff'',''hex'')) or\n       (p_media_type=''application/pdf'' and substring(v_bytes from 1 for 5)=decode(''255044462d'',''hex''))\n     ) then\n    return jsonb_build_object(''ok'', false, ''error'', ''RECEIPT_INVALID'');\n  end if;\n  v_sha := encode(extensions.digest(v_bytes,''sha256''),''hex'');\n  select id into v_id from k2_private.order_payment_receipts\n  where order_id=p_order_id and sha256=v_sha;\n  if v_id is not null then return jsonb_build_object(''ok'', true, ''receipt_id'', v_id, ''replayed'', true); end if;\n\n  select id into v_conversation_id from public.conversations\n  where source_kind=''order_request'' and source_id=p_order_id;\n  if v_conversation_id is null then\n    return jsonb_build_object(''ok'', false, ''error'', ''ORDER_CONVERSATION_UNAVAILABLE'');\n  end if;\n\n  insert into k2_private.order_payment_receipts\n    (order_id, request_key, payment_reference, media_type, byte_size, sha256, contents)\n  values (p_order_id,p_request_key,v_ref,p_media_type,octet_length(v_bytes),v_sha,v_bytes)\n  returning id into v_id;\n  insert into public.messages(conversation_id,sender_type,content,is_draft,delivery_status,direction)\n  values (v_conversation_id,''Customer'',\n    ''Payment receipt uploaded for order '' || v_order.public_reference || ''. Reference: '' || v_ref ||\n      ''. Staff must review this proof and confirm funds separately. Receipt ID: '' || v_id::text,\n    false,''received'',''inbound'');\n  update public.conversations set unread_count=coalesce(unread_count,0)+1,\n    last_inbound_at=now(), last_message_at=now(), response_due_at=now()+interval ''4 hours'',\n    updated_at=now() where id=v_conversation_id;\n  return jsonb_build_object(''ok'', true, ''receipt_id'', v_id, ''replayed'', false);\nend;\n","acl":null,"config":["search_path=\"\""],"definer":true}]'::jsonb)
  as x(identity text,before text,after text,body text,acl text[],config text[],definer boolean) loop
  select p.*,pg_get_functiondef(p.oid) definition into b from pg_proc p where oid=to_regprocedure(t.identity);
  execute replace(b.definition,b.prosrc,t.body);select * into a from pg_proc where oid=b.oid;
  if a.prosrc is distinct from t.body or (to_jsonb(a)-'prosrc') is distinct from (to_jsonb(b)-'prosrc'-'definition') then raise exception 'K2_LEGACY_WRITER_METADATA_CHANGED';end if;
 end loop;
end $legacy_writers$;
commit;
